import React, { useState, useEffect } from 'react';
import { getUsers, updateApproval } from '../../api';
import '../Dashboard.css';

function ManageHods() {
  const [hods, setHods] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getUsers().then(r => {
      const filtered = r.data.filter(u => u.role === 'hod');
      setHods(filtered);
      setLoading(false);
    });
  }, []);

  const toggleApproval = async (id, currentStatus) => {
    try {
      await updateApproval(id, !currentStatus);
      setHods(hods.map(h => h._id === id ? { ...h, isApproved: !currentStatus } : h));
    } catch (e) { alert("Update failed"); }
  };

  return (
    <div className="dashboard-outer-wrapper">
      <main className="dashboard-content">
        <h1 className="page-title">Manage HODs</h1>
        <div className="card-modern shadow-sm">
          <table className="modern-table">
            <thead>
              <tr><th>Name</th><th>Email</th><th>Department</th><th>Status</th><th>Action</th></tr>
            </thead>
            <tbody>
              {hods.map(h => (
                <tr key={h._id}>
                  <td>{h.name}</td>
                  <td>{h.email}</td>
                  <td>{h.department}</td>
                  <td><span className={`status-pill ${h.isApproved ? 'pill-completed' : 'pill-scheduled'}`}>
                    {h.isApproved ? 'Approved' : 'Pending'}
                  </span></td>
                  <td>
                    <button className="btn-done" onClick={() => toggleApproval(h._id, h.isApproved)}>
                      {h.isApproved ? 'Revoke' : 'Approve'}
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </main>
    </div>
  );
}

export default ManageHods;
